INSERT INTO destination_guidance_bullet (place_id, position, bullet_index, text) VALUES
  ('cairo', 5, 0, 'Stay in Downtown Cairo, Zamalek, Garden City, or near Giza according to your priorities, but avoid paying a premium for a pyramid or Nile view unless you will genuinely use it.'),
  ('cairo', 5, 1, 'Choose Downtown Cairo or Dokki for central access and stronger value, Zamalek for restaurants and a more relaxed atmosphere, and Giza for convenient pyramid visits and landmark views.'),
  ('cairo', 5, 2, 'Use local eateries for koshari, ful, falafel, grilled meats, and Egyptian breakfasts instead of relying only on hotel restaurants.'),
  ('cairo', 5, 3, 'Combine low-cost museums, mosques, churches, markets, Nile walks, and neighborhood exploration with a few paid highlights such as the Giza Plateau, major museum visits, and guided archaeological tours.'),
  ('cairo', 5, 4, 'Use the Cairo Metro for suitable routes, walking for compact areas, and ride-hailing for longer journeys or when traffic, heat, safety, or convenience makes it worthwhile.'),
  ('cairo', 5, 5, 'Group attractions by area, such as Giza and Saqqara together, or Islamic Cairo and Khan el-Khalili together, to reduce backtracking and unnecessary transport costs.'),
  ('cairo', 5, 6, 'Travel during the summer or shoulder season for better hotel pricing, but plan outdoor sightseeing early in the morning because Cairo’s summer heat can be intense. Budget travelers can commonly keep daily costs around USD 30–50 before international flights.'),
  ('cairo', 5, 7, 'Keep a compact itinerary and avoid changing hotels during a short 2–4-night stay.'),
  ('cairo', 5, 8, 'Where saving money is usually not recommended:'),
  ('cairo', 5, 9, 'Choosing a poorly located hotel that creates daily taxi costs, long traffic delays, and lost sightseeing time.'),
  ('cairo', 5, 10, 'Booking the absolute cheapest accommodation without checking cleanliness, reviews, air-conditioning, reception reliability, and transport access.'),
  ('cairo', 5, 11, 'Avoiding a licensed guide at the Pyramids of Giza or Saqqara if it results in confusion, negotiation stress, or missed historical context.'),
  ('cairo', 5, 12, 'Using unlicensed or unmetered taxis without agreeing on the fare beforehand; a reputable ride-hailing service or pre-arranged transfer may provide better value and predictability.'),
  ('cairo', 5, 13, 'Spending the entire trip in Western-style restaurants when local restaurants offer more authentic food at substantially lower prices.'),
  ('cairo', 5, 14, 'Overloading the itinerary with distant day trips when the main purpose is a short Cairo city break.'),
