  ('cairo', 61, 0, '**Giza** for pyramid access, landmark views, and first-time sightseeing.'),
  ('cairo', 61, 1, '**Downtown Cairo / Tahrir** for museums, central access, food, and value.'),
  ('cairo', 61, 2, '**Zamalek** for couples, restaurants, cafés, nightlife, and a calmer city atmosphere.'),
  ('cairo', 61, 3, '**Garden City / Nile Corniche** for luxury hotels, Nile views, and romantic evenings.'),
  ('cairo', 61, 4, '**Heliopolis or New Cairo** for airport convenience, business travel, or very early departures.'),
  ('cairo', 61, 5, 'Private vehicle and licensed guide for the Pyramids, Saqqara, Dahshur, and multi-site sightseeing.'),
  ('cairo', 61, 6, 'Reputable ride-hailing services for flexible city transfers.'),
  ('cairo', 61, 7, 'Cairo Metro for suitable routes and budget travel.'),
  ('cairo', 61, 8, 'Walking within compact areas such as selected parts of Islamic Cairo, Coptic Cairo, and Downtown.'),
