  ('alexandria', 144, 11, 'Multiple museums or historic sites on the same day.'),
  ('alexandria', 144, 12, 'Long walking routes in central markets and crowded streets.'),
  ('alexandria', 144, 13, 'Unplanned street-food stops.'),
  ('alexandria', 144, 14, 'Late-night activities with tired children.'),
  ('alexandria', 144, 15, 'Long cross-city journeys during peak traffic.'),
  ('alexandria', 144, 16, 'Very crowded beaches during summer weekends.'),
  ('alexandria', 144, 17, 'Staying in a distant beach district when the main plan is sightseeing.'),
  ('alexandria', 144, 18, 'Too many stairs, uneven pavements, or poorly ventilated historic interiors.'),
  ('alexandria', 145, 0, 'Keep major attraction visits to approximately 60–90 minutes for younger children.'),
  ('alexandria', 145, 1, 'Plan outdoor sightseeing between approximately 8:00 and 11:30 or during the late afternoon.'),
  ('alexandria', 145, 2, 'Combine the Bibliotheca Alexandrina, a manageable Corniche walk, and Qaitbay Citadel on one coastal day.'),
  ('alexandria', 145, 3, 'Combine the Catacombs of Kom El Shoqafa, Pompey’s Pillar, and one central museum only if the children are comfortable with archaeological sightseeing.'),
  ('alexandria', 145, 4, 'Reserve a separate, slower day for Montaza Palace Gardens, Stanley, or a beach visit.'),
  ('alexandria', 145, 5, 'Carry bottled water, snacks, sunscreen, hats, tissues, and hand sanitizer.'),
  ('alexandria', 145, 6, 'Choose restaurants with clean facilities, comfortable seating, reliable bathrooms, and familiar options such as grilled fish, grilled meat, rice, pasta, and fresh juices.'),
  ('alexandria', 145, 7, 'Introduce seafood gradually and choose well-reviewed restaurants rather than relying on unplanned street-food stops.'),
  ('alexandria', 145, 8, 'Use air-conditioned transport for distant attractions and return to the hotel during the hottest part of the day.'),
  ('alexandria', 145, 9, 'Stay close together near the Corniche, markets, harbour areas, and busy road crossings.'),
  ('alexandria', 145, 10, 'Book boat rides only with reputable operators and check life jackets before departure.'),
  ('alexandria', 145, 11, 'A private guide can shorten explanations, reduce vendor pressure, organise transport, and keep children engaged with stories and activities.'),
  ('alexandria', 145, 12, 'Check attraction opening times, ticket rules, photography restrictions, toilets, shade, and accessibility before visiting.'),
  ('alexandria', 146, 0, 'Stay at a high-quality sea-view hotel around the Central Corniche, Bibliotheca Alexandrina, Stanley, San Stefano, or Montaza.'),
  ('alexandria', 146, 1, 'Choose a romantic waterfront area with Mediterranean views, sunset opportunities, and access to restaurants and cafés.'),
  ('alexandria', 146, 2, 'Plan one memorable experience each evening rather than filling the itinerary with attractions.'),
  ('alexandria', 146, 3, 'Enjoy a private harbour or coastal boat ride at sunset.'),
  ('alexandria', 146, 4, 'Have one premium seafood dinner overlooking the Mediterranean.'),
  ('alexandria', 146, 5, 'Take a private guided visit to the Bibliotheca Alexandrina and Qaitbay Citadel.'),
  ('alexandria', 146, 6, 'Explore Montaza Palace Gardens at a relaxed pace.'),
  ('alexandria', 146, 7, 'Enjoy a quiet waterfront café, rooftop meal, hotel lounge, or sunset Corniche walk.'),
  ('alexandria', 146, 8, 'Arrange a private car and driver for archaeological sites and cross-city transfers.'),
  ('alexandria', 146, 9, 'Leave plenty of free time for the hotel, pool, spa, cafés, photography, and leisurely seaside walks.'),
  ('alexandria', 146, 10, 'Consider a private photography or architecture walk through the historic harbour districts.'),
  ('alexandria', 148, 0, '**Central Corniche / Bibliotheca area** – for sea views, convenient access to the Library, central waterfront attractions, cafés, and romantic evening walks.'),
  ('alexandria', 148, 1, '**Qaitbay / Western Harbour area** – for historic atmosphere, harbour views, seafood restaurants, sunset photography, and close access to Qaitbay Citadel.'),
  ('alexandria', 148, 2, '**Stanley / Eastern Corniche** – for Mediterranean views, Stanley Bridge, modern hotels, cafés, relaxed coastal walks, and attractive sunset settings.'),
  ('alexandria', 148, 3, '**San Stefano / Eastern Waterfront** – for upscale hotels, shopping, contemporary facilities, premium dining, and comfortable hotel-based relaxation.'),
  ('alexandria', 148, 4, '**Montaza / Palace Gardens area** – for gardens, spacious surroundings, coastal scenery, beach access, and a slower resort-style atmosphere.'),
  ('alexandria', 148, 5, '**Luxury sea-view stays** – for premium service, private balconies, hotel pools, spa facilities, concierge support, and memorable sunset experiences.'),
  ('alexandria', 148, 6, '**Central Alexandria / Raml Station area** – only if access to historic streets, local cafés, markets, and central restaurants matters more than privacy and quiet.'),
  ('alexandria', 149, 0, 'Stay at a 5-star sea-view hotel in the Central Corniche, Stanley, San Stefano, or Montaza area.'),
  ('alexandria', 149, 1, 'Choose a suite, premium sea-view room, or private residence with a balcony overlooking the Mediterranean.'),
  ('alexandria', 149, 2, 'Arrange a private airport transfer from Cairo International Airport in a luxury sedan or premium MPV.'),
  ('alexandria', 149, 3, 'Use a chauffeured vehicle for sightseeing, restaurant transfers, shopping, and cross-city journeys.'),
  ('alexandria', 149, 4, 'Hire a private Egyptologist or specialist cultural guide for Qaitbay Citadel, the Catacombs of Kom El Shoqafa, Pompey’s Pillar, and Kom El-Dikka.'),
  ('alexandria', 149, 5, 'Arrange a private guided visit to the Bibliotheca Alexandrina, including selected museums or cultural spaces.'),
  ('alexandria', 149, 6, 'Enjoy fine seafood dining at a premium waterfront restaurant or luxury hotel.'),
  ('alexandria', 149, 7, 'Book a private harbour cruise or sunset boat ride with a reputable operator.'),
  ('alexandria', 149, 8, 'Explore Montaza Palace Gardens with private transport, photography stops, and time for a relaxed meal.'),
  ('alexandria', 149, 9, 'Arrange a curated historic architecture, literary, or photography tour through central Alexandria and the harbour districts.'),
