INSERT INTO destination_guidance_bullet (place_id, position, bullet_index, text) VALUES
  ('batumi', 677, 2, 'Avoid stacking multiple walking-intensive attractions or long outdoor excursions in one day.'),
  ('batumi', 677, 3, 'Include regular seating, rest, meals, hydration, and comfortable breaks during sightseeing.'),
  ('batumi', 677, 4, 'Check hotel accessibility, lifts, ground-floor rooms, bathroom facilities, heating/air-conditioning, and vehicle access before booking.'),
  ('batumi', 677, 5, 'Prefer senior-friendly attractions such as Batumi Boulevard, Europe Square, Piazza, Miracle Park, museums, selected Old Batumi areas, and waterfront attractions.'),
  ('batumi', 677, 6, 'Use the Argo Cable Car where appropriate to reduce demanding uphill walking while enjoying panoramic views.'),
  ('batumi', 677, 7, 'Avoid unnecessary long walks on uneven surfaces, steep paths, or extensive nature trails.'),
  ('batumi', 677, 8, 'Schedule major sightseeing during comfortable daytime hours and avoid prolonged outdoor exposure during extreme summer heat, heavy rain, or strong coastal weather.'),
  ('batumi', 677, 9, 'Allow additional transition time between attractions because traffic, pedestrian areas, walking distances, and seasonal congestion can affect travel time.'),
  ('batumi', 677, 10, 'Avoid unnecessarily long public-transport journeys when comfort or mobility is a concern.'),
  ('batumi', 677, 11, 'Keep the itinerary flexible around weather, temperature, walking ability, and attraction conditions.'),
  ('batumi', 677, 12, 'Give extra consideration to Batumi Botanical Garden, Mtirala National Park, Gonio Fortress, and other nature or historic areas because some routes involve slopes, steps, uneven paths, or extended walking.'),
  ('batumi', 677, 13, 'Prefer private transport for longer excursions into the wider Adjara region when comfort and mobility are priorities.'),
  ('batumi', 678, 0, 'Batumi has made accessibility improvements in public transport, tourist sites, hotels and recreational areas, but accessibility remains uneven across the destination.'),
  ('batumi', 678, 1, 'Batumi Boulevard is one of the more suitable areas for accessible sightseeing, with relatively wide promenades, recreational spaces and adapted infrastructure in parts of the coastal area.'),
  ('batumi', 678, 2, 'Some sections of Batumi Beach have accessible infrastructure, including adapted walkways, showers, changing facilities and floating wheelchairs; availability should be confirmed before travel.'),
  ('batumi', 678, 3, 'Official Batumi tourism information identifies Batumi Boulevard, Old Batumi, the port area, the Botanical Garden and Dolphinarium among tourist sites equipped with facilities for disabled visitors.'),
  ('batumi', 678, 4, 'Municipal buses are adapted for passengers with disabilities, making them a useful accessible public-transport option, although the specific vehicle, route and stop should still be checked.'),
  ('batumi', 678, 5, 'Several Batumi hotels are officially listed as having adapted rooms or facilities, including Hilton Batumi, Sheraton Batumi, Radisson, Euphoria, Intourist Palace and Wyndham Batumi; room availability should be confirmed directly before booking.'),
  ('batumi', 678, 6, 'Old Batumi contains historic streets and buildings where accessibility can vary because of older construction, uneven surfaces, steps and narrow sections.'),
  ('batumi', 678, 7, 'Batumi Botanical Garden contains extensive outdoor terrain and pathways, so wheelchair users should confirm suitable routes and current conditions before visiting.'),
  ('batumi', 678, 8, 'The Argo Cable Car provides access from Old Batumi toward Mount Anuria and can reduce the need for demanding uphill travel, but accessibility of boarding areas, cabins and the upper complex should be confirmed for individual mobility requirements.'),
  ('batumi', 678, 9, 'Mountainous Adjara excursions, hiking routes, waterfalls and rural attractions generally present greater accessibility challenges because of slopes, natural terrain, uneven paths and road conditions.'),
  ('batumi', 678, 10, 'Travelers with significant mobility requirements should prioritize accessible hotels, Batumi Boulevard, suitable beach sections, accessible municipal buses and verified tourist attractions.'),
  ('batumi', 678, 11, 'Taxis or private vehicles can provide greater flexibility for travelers with mobility requirements, particularly for attractions outside central Batumi and mountainous Adjara.'),
  ('batumi', 678, 12, 'Accessibility information should be confirmed directly with hotels, attractions, transport operators or Batumi/Adjara tourist information services before booking or travel. Batumi''s official tourist information centres can provide current destination and transport guidance.'),
