  ('gori', 717, 12, 'UPLISTSIKHE_CLIFF_AND_CAVE_EXPLORATION'),
  ('gori', 717, 13, 'UPLISTSIKHE_ARCHAEOLOGICAL_LANDSCAPE_EXPLORATION'),
  ('gori', 717, 14, 'MOUNTAIN_AND_VALLEY_SCENIC_DRIVES'),
  ('gori', 717, 15, 'COUNTRYSIDE_EXPLORATION'),
