INSERT INTO destination_guidance_bullet (place_id, position, bullet_index, text) VALUES
  ('germany', 2436, 20, 'Do not underestimate ICE travel, station time, luggage, and hotel changes.'),
  ('germany', 2436, 21, 'Do not rent a car automatically for major-city itineraries.'),
  ('germany', 2436, 22, 'Do not ignore Rhine / Moselle, Black Forest, Romantic Road, or Saxony.'),
  ('germany', 2436, 23, 'Do not focus only on WWII / Cold War history and miss Germany''s wider heritage and contemporary culture.'),
  ('germany', 2436, 24, 'Do not ignore Oktoberfest, major fairs, festivals, and Christmas-market demand.'),
  ('germany', 2436, 25, 'Do not overload families with museum-heavy days.'),
  ('germany', 2436, 26, 'Do not assume castles, medieval towns, or nature trails are uniformly step-free.'),
  ('germany', 2436, 27, 'Do not sacrifice food, wine, parks, river cruises, spa, or free time simply to increase destination count.'),
  ('germany', 2437, 0, 'Germany Travel — Official information on German cities, culture, museums, regional destinations, castles, nature, family travel, food, and national tourism planning.'),
  ('germany', 2437, 1, 'Germany Travel / Rail Travel — Information on ICE and regional rail, major-city connections, rail-based destination touring, and travel convenience.'),
  ('germany', 2437, 2, 'Germany Travel / Family — Information on family-friendly cities, museums, zoos, parks, cycling, and regional family excursions.'),
  ('germany', 2437, 3, 'Germany Travel / Tourism for All — Certified and independently verified accessibility information covering accommodation, attractions, dining, nature, shopping, and other tourism services.'),
  ('germany', 2437, 4, 'Germany Travel / Christmas — Seasonal positioning of Christmas markets throughout Germany.'),
