INSERT INTO destination_guidance_bullet (place_id, position, bullet_index, text) VALUES
  ('poland', 2691, 16, 'Craft beer brewpub tours'),
  ('poland', 2691, 17, 'Vodka tasting bars'),
  ('poland', 2691, 18, 'Rooftop cocktail lounges'),
