INSERT INTO destination_guidance_bullet (place_id, position, bullet_index, text) VALUES
  ('ha-long-bay', 3874, 10, 'Rock climbers and deep-water soloists.'),
  ('ha-long-bay', 3874, 11, 'Hikers and trail enthusiasts.'),
  ('ha-long-bay', 3874, 12, 'Landscape and outdoor photographers.'),
  ('ha-long-bay', 3874, 13, 'Active couples and adventure travelers.'),
  ('ha-long-bay', 3874, 14, 'Families with teenagers seeking outdoor activities.'),
  ('ha-long-bay', 3875, 0, 'Choose larger, modern 5-star cruise vessels equipped with spacious cabins, wide corridors, stable tender embarkation, and minimal steep staircases.'),
  ('ha-long-bay', 3875, 1, 'Use private expressway transfers from Hanoi to ensure a smooth, comfortable 2.5-hour journey directly to the harbor.'),
  ('ha-long-bay', 3875, 2, 'Limit active outings to 1 key excursion daily, utilizing optional deck relaxation during strenuous activities.'),
  ('ha-long-bay', 3875, 3, 'Confirm vessel accessibility, handrails, tender boat assistance, and dietary preferences before booking.'),
  ('ha-long-bay', 3875, 4, 'Opt for bamboo rowboat excursions guided by local villagers instead of self-paddled sea kayaking.'),
  ('ha-long-bay', 3875, 5, 'Schedule deck time and viewing during cooler morning or late-afternoon hours.'),
  ('ha-long-bay', 3875, 6, 'Prioritize comfort, scenic relaxation, and a relaxed sailing pace.'),
  ('ha-long-bay', 3875, 7, 'Panoramic deck relaxation, sunrise Tai Chi, and cooking demonstrations onboard the cruise vessel.'),
  ('ha-long-bay', 3875, 8, 'Guided bamboo rowboat tours through scenic sea arches like Luon Cave or Dark & Bright Cave.'),
  ('ha-long-bay', 3875, 9, 'Vessels sailing Lan Ha Bay or Bai Tu Long Bay for calmer waters and fewer harbor crowds.'),
  ('ha-long-bay', 3875, 10, 'Ground-level or elevator-accessible cabins with private oceanfront balconies and walk-in showers.'),
  ('ha-long-bay', 3875, 11, 'Chauffeured limousine van transfers to eliminate transit stress between Hanoi and the bay.'),
  ('ha-long-bay', 3875, 12, 'Experienced cruise staff and reputable, licensed maritime operators.'),
  ('ha-long-bay', 3875, 13, 'Steep, uneven cavern climbs with hundreds of stone steps (such as the upper ascent of Sung Sot Cave or Titov Island peak).'),
  ('ha-long-bay', 3875, 14, 'Budget day-boats with cramped seating, steep boarding ladders, and unstable tender transfers.'),
  ('ha-long-bay', 3875, 15, 'Self-paddled kayaking in open or windy water passages.'),
  ('ha-long-bay', 3875, 16, 'Multi-stop land tours requiring frequent transfer changes and heavy walking.'),
  ('ha-long-bay', 3875, 17, 'Unassisted boarding onto small tender boats during rough weather.'),
  ('ha-long-bay', 3875, 18, 'Rushed 1-day express trips from Hanoi that involve 5–6 hours of transit in a single day.'),
  ('ha-long-bay', 3877, 0, 'Sampling *Chả Mực* (hand-pounded fried squid patties), the signature culinary icon of Ha Long Bay.'),
  ('ha-long-bay', 3877, 1, 'Fresh seafood feasts onboard overnight cruises featuring mantis shrimp, mud crab, squid, and sea snails.'),
  ('ha-long-bay', 3877, 2, 'Enjoying *Bún Hải Sản* (spicy seafood noodle soup) at local morning markets in Ha Long City.'),
  ('ha-long-bay', 3877, 3, 'Dining on floating seafood platforms in Lan Ha Bay, choosing live fish and shellfish straight from the net.'),
  ('ha-long-bay', 3877, 4, 'Interactive Vietnamese spring roll cooking masterclasses on the open sun deck of a cruise vessel.'),
  ('ha-long-bay', 3877, 5, '**Families:** Onboard interactive cooking demonstrations and fresh, kid-friendly grilled seafood options.'),
  ('ha-long-bay', 3877, 6, '**Honeymooners:** Romantic candlelit multi-course dinners served on private cabin balconies or inside sea caves.'),
  ('ha-long-bay', 3877, 7, '**Luxury travelers:** Fine dining paired with sommelier selections and gourmet fusion menus prepared by private onboard chefs.'),
  ('ha-long-bay', 3877, 8, '**Budget travelers:** Affordable local night market stalls, street-side noodle shops, and seafood markets in Bãi Cháy.'),
  ('ha-long-bay', 3877, 9, '**Foodies:** Authentic northern maritime dishes, local squid specialties, and fresh catches from regional fishing villages.'),
  ('ha-long-bay', 3877, 10, '**Central Ha Long Bay / Cruise Vessels:** Best for multi-course seafood banquets, sun deck cooking classes, and cave dining experiences.'),
  ('ha-long-bay', 3877, 11, '**Ha Long City & Bãi Cháy:** Best for vibrant night market street food, authentic *Chả Mực* stalls, and local seafood halls.'),
  ('ha-long-bay', 3877, 12, '**Cat Ba Island (Land Hub):** Best for casual harbor-front seafood restaurants, budget local eateries, and night market grilled skewers.'),
  ('ha-long-bay', 3877, 13, '**Lan Ha Bay Floating Rafts:** Best for fresh live-seafood catches selected directly from floating farm enclosures.'),
  ('ha-long-bay', 3877, 14, '**Tuan Chau Marina:** Best for pre-embarkation waterfront dining, cafes, and upscale mainland seafood venues.'),
  ('ha-long-bay', 3878, 0, '**Cultured Pearls:** High-quality saltwater pearls, loose or set in silver/gold jewelry, sourced directly from local pearl farms.'),
  ('ha-long-bay', 3878, 1, '**Ha Long Squid Patties (*Chả Mực*):** Vacuum-sealed packs of hand-pounded fried squid, a celebrated local delicacy to take home.'),
  ('ha-long-bay', 3878, 2, '**Handicrafts & Souvenirs:** Wooden junk model ships, seashell crafts, bamboo products, and traditional Vietnamese lacquerware.'),
  ('ha-long-bay', 3878, 3, '**Local Teas & Spirits:** Regional Vietnamese green teas, lotus tea, and local rice spirits (*Rượu*).'),
  ('ha-long-bay', 3878, 4, '**Silk & Textiles:** Embroidered garments, scarves, and traditional *Áo Dài* tailormade or ready-to-wear.'),
  ('ha-long-bay', 3878, 5, '**Ha Long City & Bãi Cháy** for the Bãi Cháy Night Market and Ha Long Market (Chợ Hạ Long 1) for local food items, dried seafood, and handicrafts.'),
  ('ha-long-bay', 3878, 6, '**Floating Pearl Farms (Central Bay / Lan Ha)** for authentic, certified pearl cultivation demonstrations and jewelry purchases.'),
  ('ha-long-bay', 3878, 7, '**Tuan Chau Marina** for upscale boutique gift shops selling high-end Vietnamese silk, tea, and artwork before boarding.'),
  ('ha-long-bay', 3878, 8, '**Cat Ba Town Market** for dried seafood, sea-salt products, and local island honey harvested from Cat Ba National Park.'),
  ('ha-long-bay', 3878, 9, '**Hon Gai Local Market** for non-touristy, authentic local prices on teas, spices, and regional specialties.'),
  ('ha-long-bay', 3878, 10, 'Buying pearls from unaccredited street stalls or beach vendors, as counterfeit plastic/shell beads are common.'),
  ('ha-long-bay', 3878, 11, 'Overpaying for mass-produced wooden boat models at tourist rest-stops along the Hanoi-Ha Long expressway.'),
