INSERT INTO destination_guidance_bullet (place_id, position, bullet_index, text) VALUES
  ('lucknow', 6893, 0, 'Use Lucknow Metro for airport, Charbagh, Hazratganj and other stations served by the operational corridor.'),
  ('lucknow', 6893, 1, 'Use e-rickshaws and auto-rickshaws for short local connections where appropriate.'),
  ('lucknow', 6893, 2, 'Stay around Charbagh, Hazratganj edges, Aminabad or other centrally connected neighborhoods rather than selecting premium luxury areas.'),
  ('lucknow', 6893, 3, 'Eat local kebabs, biryani, chaat, kulcha, sweets and vegetarian dishes instead of relying entirely on luxury-hotel restaurants.'),
  ('lucknow', 6893, 4, 'Combine Bara Imambara, Rumi Darwaza and Husainabad attractions geographically.'),
  ('lucknow', 6893, 5, 'Combine Chowk food exploration with Chikankari and craft shopping.'),
  ('lucknow', 6893, 6, 'Use public parks, markets, riverfront areas and heritage streets as low-cost sightseeing.'),
  ('lucknow', 6893, 7, 'Negotiate or confirm local transport fares before non-metered journeys.'),
  ('lucknow', 6893, 8, 'Booking accommodation extremely far from Old Lucknow simply to save a small amount.'),
  ('lucknow', 6893, 9, 'Selecting very low-quality food outlets without basic hygiene standards merely because street-food prices are cheaper.'),
  ('lucknow', 6893, 10, 'Purchasing supposedly handmade Chikankari without checking fabric quality, embroidery detail and authenticity.'),
  ('lucknow', 6893, 11, 'Using multiple inefficient local transfers instead of a direct cab when traveling with seniors, children or substantial luggage.'),
  ('lucknow', 6893, 12, 'Scheduling multiple isolated heritage sites without geographic clustering.'),
  ('lucknow', 6893, 13, 'Skipping a proper Awadhi meal; gastronomy is one of Lucknow''s strongest destination assets.'),
