INSERT INTO destination_guidance_bullet (place_id, position, bullet_index, text) VALUES
  ('agra', 6953, 10, 'Resort boutiques at The Oberoi Amarvilas, ITC Mughal, and Taj Hotel'),
  ('agra', 6953, 11, 'Government-approved Emporiums for certified marble inlay and carpets'),
  ('agra', 6953, 12, 'Premium artisan studios in Gokulpura'),
  ('agra', 6953, 13, 'Sadar Bazaar market shops for leather goods and handicrafts'),
  ('agra', 6953, 14, 'Kinari Bazaar wholesale market lanes for textiles, spices, and souvenirs'),
  ('agra', 6953, 15, 'Original Panchhi Petha stores for local sweet boxes at standard prices'),
  ('agra', 6953, 16, 'Gokulpura wholesale marble shops for factory-direct prices'),
  ('agra', 6953, 17, 'Street stalls along Taj East Gate Road promenade'),
  ('agra', 6954, 0, 'Couples'),
  ('agra', 6954, 1, 'Luxury hotel lounge relaxers'),
  ('agra', 6954, 2, 'Cultural show enthusiasts (Mohabbat the Taj)'),
  ('agra', 6954, 3, 'Fine dining lovers (Royal Mughlai feasts)'),
  ('agra', 6954, 4, 'Evening street-food night market enjoyers'),
  ('agra', 6954, 5, 'Fatehabad Road (High-end hotel bars, rooftop lounges, multi-cuisine dining hubs)'),
  ('agra', 6954, 6, 'Sadar Bazaar & Chaat Gali (Bustling night shopping lanes, evening street food, dessert stalls)'),
  ('agra', 6954, 7, 'Taj East Gate Road (Quiet hotel lounges, cultural centers, pedestrian walkways)'),
  ('agra', 6954, 8, 'Cantonment Hubs (Upscale pub centers, hotel bars, sports lounges)'),
  ('agra', 6954, 9, 'Watching the sunset over the Taj Mahal from Mehtab Bagh or hotel rooftop lounges'),
  ('agra', 6954, 10, 'Attending the live Mohabbat the Taj theatrical musical show at Kalakriti Cultural Center'),
  ('agra', 6954, 11, 'Enjoying evening drinks at luxury hotel rooftop bars overlooking the illuminated city skyline'),
  ('agra', 6954, 12, 'Casual evening walks and chaat tasting along Sadar Bazaar Chat Gali'),
  ('agra', 6954, 13, 'Starlight dining at royal Mughlai courtyard restaurants with live classical sitar music'),
  ('agra', 6954, 14, 'Full-moon night viewing of the Taj Mahal (available 5 nights a month around full moon)'),
  ('agra', 6954, 15, 'Late-night Petha and dessert sampling at local sweet markets'),
  ('agra', 6977, 0, 'Treat Agra as only Taj Mahal + Agra Fort and miss Fatehpur Sikri heritage, Mehtab Bagh sunset panoramas, Tomb of I''timād-ud-Daulah (Baby Taj), and UNESCO-nominated Keoladeo National Park sites.'),
  ('agra', 6977, 1, 'Overload Day 1 with Taj Mahal, Agra Fort, Akbar''s Tomb at Sikandra, Baby Taj, and a Mohabbat the Taj cultural show all within a single 24-hour window.'),
  ('agra', 6977, 2, 'Try to combine Agra + Fatehpur Sikri + Bharatpur + Mathura + Vrindavan in a short itinerary simply because Golden Triangle road connections look short on a map.'),
  ('agra', 6977, 3, 'Rely entirely on narrow city center auto-rickshaws during peak morning rush hours, or ignore Agra''s electric battery cart network in non-motorized monument zones and convenient Yamuna Expressway private car rentals.'),
  ('agra', 6977, 4, 'Underestimate advance online ticket booking rules and strict daily ticket limits for Taj Mahal main mausoleum access, high-speed Gatimaan Express train seats, and Wildlife SOS sanctuary visits during peak winter holiday seasons.'),
  ('agra', 6977, 5, 'Treat Agra''s climate as uniform and ignore seasonal extremes between scorching summer heat, dense winter morning fog disruption on expressways, and humid monsoon spillover windows.'),
  ('agra', 6977, 6, 'Plan outdoor Tajganj heritage walks, open-air Mehtab Bagh gardens, or Fatehpur Sikri ridge walks without checking temperature forecasts, dense fog mornings, or extreme weekend tourist crowds.'),
  ('agra', 6977, 7, 'Ignore Mughlai gastronomy by treating meals only as international hotel buffets instead of scheduling authentic Bedai-Kachori, Mughlai Tandoori Kebabs, Sadar Bazaar Street Chaat, Fresh Jalebi, and Agra Petha.'),
  ('agra', 6977, 8, 'Schedule excessive hotel moves between Tajganj and Fatehabad Road even when a single central base along Fatehabad Road or near Taj East Gate serves the entire city efficiently.'),
  ('agra', 6977, 9, 'Assume every red sandstone monument, marble stair complex, and historic Mughal garden path is automatically step-free or fully accessible.'),
  ('agra', 6978, 0, 'Builds first-time itineraries around TAJ_MAHAL_SUNRISE + AGRA_FORT_HERITAGE + FATEHPUR_SIKRI_SANCTUARY + MEHTAB_BAGH_AND_BABY_TAJ.'),
  ('agra', 6978, 1, 'Gives Tajganj & Old Agra Market enough time for heritage walks, Mughal architecture photography, and afternoon shaded market strolls without rushing.'),
  ('agra', 6978, 2, 'Gives Fatehpur Sikri or Wildlife SOS trips enough time for HISTORIC_PALACE_STROLL + HIGHWAY_DHABA_DINING + EMBROIDERY_HANDICRAFT_VISITS rather than treating them as rushed side trips.'),
  ('agra', 6978, 3, 'Adds AKBARS_TOMB_AT_SIKANDRA & ITIMAD_UD_DAULAH for Mughal heritage, tomb architecture history, and traditional Pietra Dura marble inlay culture.'),
  ('agra', 6978, 4, 'Uses TAJ_MUSEUM / KALAKRITI_CULTURAL_CENTER selectively when Mughal history, marble craftsmanship, and Indian performing arts exhibitions are the focus.'),
  ('agra', 6978, 5, 'Uses MEHTAB_BAGH / KEOLADEO_NATIONAL_PARK / SUR_SAROVAR_BIRD_SANCTUARY when riverfront walks, wetland nature trails, and migratory bird viewing are preferred.'),
  ('agra', 6978, 6, 'Uses PRIVATE_AC_CARS and GATIMAAN_EXPRESS_TRAINS for regional transit, and electric battery carts or luxury MPVs for monument arrival and local moves.'),
  ('agra', 6978, 7, 'Keeps time for Fatehabad Road cafes, Mughal garden tea houses, Yamuna riverfront promenades, and relaxed heritage-style strolling.'),
  ('agra', 6978, 8, 'Matches outdoor sightseeing, monument photography, and rooftop observation decks to seasonal weather, morning fog levels, and daylight conditions.'),
  ('agra', 6978, 9, 'For first-time visits, prioritize:'),
  ('agra', 6981, 0, 'WALKING + ELECTRIC_BATTERY_CARTS for Taj East Gate eco-zone, Tajganj, and Mehtab Bagh gardens'),
  ('agra', 6981, 1, 'AGRA_METRO (YELLOW_LINE) for fast transit between Taj East Gate, Taj Mahal Ramp, and Mankameshwar / Old City'),
  ('agra', 6981, 2, 'PRIVATE_AC_CARS / TAXIS selectively for Fatehpur Sikri, Wildlife SOS, Mathura day trips, and late-night movements'),
  ('agra', 6981, 3, 'GATIMAAN_EXPRESS_AND_SHATABDI_TRAINS for rapid intercity transit between Agra Cantt (AGC) and Delhi NCR / Jaipur'),
  ('agra', 6981, 4, 'YAMUNA_EXPRESSWAY_PRIVATE_TRANSFERS for direct highway connections to Indira Gandhi International Airport (DEL)'),
  ('agra', 6981, 5, 'ELECTRIC_AUTO_RICKSHAWS selectively for quick local connections across Agra Fort and Sadar Bazaar lanes'),
  ('agra', 6981, 6, 'Taj Mahal sunrise entry & marble reflection pool sensory exploration'),
  ('agra', 6981, 7, 'Agra Fort grand sandstone ramparts & Musamman Burj view walk'),
  ('agra', 6981, 8, 'Fatehpur Sikri deserted royal city & Buland Darwaza exploration'),
  ('agra', 6981, 9, 'Signature Agra Bedai-Kachori & Jalebi breakfast tasting at Old City food stalls'),
  ('agra', 6981, 10, 'Mehtab Bagh riverbank garden promenade & sunset Taj view'),
  ('agra', 6981, 11, 'Tomb of I''timād-ud-Daulah (Baby Taj) master Pietra Dura inlay tour'),
  ('agra', 6981, 12, 'Sadar Bazaar handicraft shopping & authentic leather goods walk'),
  ('agra', 6981, 13, 'Wildlife SOS Elephant Conservation and Care Center interactive tour'),
  ('agra', 6981, 14, 'Mohabbat the Taj theatrical performance at Kalakriti Cultural Center'),
  ('agra', 6981, 15, 'Akbar''s Tomb at Sikandra Charbagh walk among free-roaming wildlife'),
  ('agra', 6981, 16, 'Do not treat Agra as only resort pools while skipping local Mughal heritage sites and preserved imperial tombs.'),
  ('agra', 6981, 17, 'Do not force Taj Mahal + Agra Fort + Fatehpur Sikri + Wildlife SOS + Mathura day trip all into a single 24-hour window.'),
  ('agra', 6981, 18, 'Do not underestimate advance online ticket booking rules for Taj Mahal main mausoleum access, high-speed train seats, and peak holiday resort bookings.'),
  ('agra', 6981, 19, 'Do not rely solely on city buses during late evening hours when routes run infrequently and metro/car rentals offer fixed convenience.'),
  ('agra', 6981, 20, 'Do not visit Mehtab Bagh observation decks on dense fog winter mornings without checking live visibility forecasts.'),
  ('agra', 6981, 21, 'Do not plan extensive outdoor monument walks without checking seasonal weather, heat advisories (over 40°C in summer), and heavy humidity.'),
  ('agra', 6981, 22, 'Do not miss Mughlai fusion gastronomy by eating only standard Western hotel buffets.'),
  ('agra', 6981, 23, 'Do not assume historic red sandstone steps, tomb thresholds, and garden pathways are fully step-free or barrier-free.'),
  ('agra', 6981, 24, 'Do not ignore physical scale; massive fort complexes and expansive imperial palace grounds require reasonable physical stamina.'),
  ('agra', 6982, 0, 'Uttar Pradesh Tourism (uptourism.gov.in) — Official government tourism board details covering World Heritage monuments, cultural events, circuit maps, and heritage itineraries.'),
  ('agra', 6982, 1, 'Archaeological Survey of India (ASI) — Official ticket entry guidelines, sunrise/sunset opening schedules, Friday closure rules for Taj Mahal, and conservation updates for Agra monuments.'),
  ('agra', 6982, 2, 'Uttar Pradesh Metro Rail Corporation (UPMRC) & Indian Railways (IRCTC) — Agra Metro Priority Corridor network maps, Gatimaan/Shatabdi Express schedules, and station accessibility updates.'),
  ('agra', 6982, 3, 'India Meteorological Department (IMD) — Seasonal climate data, summer heat warning protocols, winter fog advisories, and monsoon weather patterns.'),
  ('agra', 6982, 4, 'Official venue operators — Wildlife SOS Elephant Conservation Center, Kalakriti Cultural Center, The Oberoi Amarvilas, and UP Ecotourism Development Board.'),
