  ('ayodhya', 7033, 0, 'TEMPLE_DARSHAN'),
  ('ayodhya', 7033, 1, 'HERITAGE_WALKS'),
  ('ayodhya', 7033, 2, 'SARYU_BOAT_RIDES'),
  ('ayodhya', 7033, 3, 'RAM_JANMABHOOMI_CIRCUIT'),
  ('ayodhya', 7033, 4, 'STREET_FOOD_TOURS'),
  ('ayodhya', 7033, 5, 'PHOTOGRAPHY'),
