  ('trivandrum:rule:7', 'trivandrum', 'prefer_ksrtc_buses_for_direct_corridors AND: prefer_central_city_hotel_near_transport_hubs AND: mix_free_beaches_and_low_cost_museums', 'Maintains destination experience quality while systematically minimizing unnecessary transport and lodging costs. ---'),
  ('visakhapatnam:rule:0', 'visakhapatnam', 'RK Beach + Kailasagiri sunset + Submarine Museum + Aquarium + Beach Road + Rushikonda Beach quick. No Araku.', 'Araku needs a full day + ghat 3hr.'),
  ('visakhapatnam:rule:1', 'visakhapatnam', 'Day 1 Vizag city beaches + Kailasagiri + Submarine + Simhachalam, Day 2 Araku + Borra day trip 6 AM-8 PM Vistadome or private car + coffee + Tribal Museum. Core.', 'Covers beach + hills + caves.'),
  ('visakhapatnam:rule:2', 'visakhapatnam', 'Add Rushikonda water sports + Yarada + Bheemili + Thotlakonda + Katiki Waterfalls trek + Tyda + Ananthagiri + Lambasingi + Araku overnight coffee resort.', 'Complete beach + hills + caves + waterfalls + coffee.'),
  ('visakhapatnam:rule:3', 'visakhapatnam', 'Kailasagiri park + ropeway + toy train + Submarine + Aquarium + Rushikonda water sports + Araku Vistadome + Borra + Tribal Museum + Zoo + bamboo chicken.', 'Family beach + park + train + caves + zoo.'),
  ('visakhapatnam:rule:4', 'visakhapatnam', 'Rushikonda sea view resort + private balcony + private beach dinner + Araku coffee resort private cottage + valley view + Kailasagiri sunset private + Yarada private + Dolphin''s Nose sunset.', 'Beach + hills combo romantic.'),
  ('visakhapatnam:rule:5', 'visakhapatnam', 'Best season + beach + Araku + coffee + pleasant + book resorts early + Rushikonda swimming + Vistadome best.', 'Peak pleasant. ---'),
  ('hyderabad:rule:0', 'hyderabad', 'Old City Charminar + Chowmahalla + Salar Jung + Laad Bazaar + Mecca Masjid + Nimrah chai + Hussain Sagar boat sunset + Birla Mandir + Golconda sunset light & sound + biryani 2 times. No Ramoji.', 'Ramoji needs a full day.'),
  ('hyderabad:rule:1', 'hyderabad', 'Day 1 Old City + Salar Jung + Hussain Sagar + Birla Mandir + biryani, Day 2 Golconda + Qutb Shahi + Shilparamam + Banjara Hills + Ramoji half day or full day if family. Core.', 'Covers history + pearls + biryani + fort + lake.'),
  ('hyderabad:rule:2', 'hyderabad', 'Add Ramoji Film City full day 9 AM-8 PM + Bahubali set + Ananthagiri Hills 80km + Chilkur Balaji + Sanghi Temple + Falaknuma Palace high tea + shopping pearls + Pochampally + GVK One + Durgam Cheruvu.', 'Complete family + luxury + offbeat + business + shopping.'),
  ('hyderabad:rule:3', 'hyderabad', 'Ramoji Film City full day + Hussain Sagar boat + NTR Gardens + Snow World + Birla Planetarium + Zoo + Shilparamam + Salar Jung + Golconda light & sound + Charminar + biryani.', 'Family entertainment + Bahubali + film city + lake + gardens.'),
  ('hyderabad:rule:4', 'hyderabad', 'HITEC City + Gachibowli + Financial District + conventions + 5★ business hotels + Banjara Hills meetings + Old City quick tour + Golconda evening + biryani business dinner + Shilparamam.', 'Business hub + conventions + IT.'),
  ('hyderabad:rule:5', 'hyderabad', 'Best season + Old City walkable + Golconda sunset + Hussain Sagar + Ramoji + biryani + pearls shopping + book Falaknuma early.', 'Peak pleasant. ---'),
